def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    dangerous_bid = 0.0
    rich_alive = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 1.2:
                rich_alive += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = float(prev['bid'])
                prev_bids.append(b)
                if b > dangerous_bid:
                    dangerous_bid = b

    if not alive_opponents:
        return float(min(budget, 18.0 if hp > 3 else 40.0))

    total_alive = 1 + len(alive_opponents)
    likely_units = supply / float(WATER_REQ)
    scarcity = likely_units < total_alive

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1
    if day >= 8:
        urgency += 1

    if prev_bids:
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        avg_prev = 0.0

    if scarcity:
        if urgency >= 5:
            target = max(90.0, dangerous_bid + 3.0, avg_prev + 8.0)
        elif urgency >= 3:
            target = max(58.0, min(95.0, avg_prev * 0.85 + 6.0))
            if dangerous_bid >= 120.0:
                target = min(target, 52.0)
        else:
            if dangerous_bid >= 100.0 or rich_alive >= 2:
                target = 16.0
            else:
                target = max(22.0, min(45.0, avg_prev * 0.55 + 4.0))
    else:
        if urgency >= 5:
            target = max(62.0, avg_prev + 2.0)
        elif urgency >= 3:
            target = max(38.0, min(62.0, avg_prev * 0.7 + 3.0))
        else:
            target = 20.0 if dangerous_bid >= 90.0 else 28.0

    if budget < DAILY_SALARY:
        target = min(target, budget * (0.72 if urgency < 4 else 0.92))
    else:
        reserve_days = max(0, 10 - day)
        soft_cap = budget / max(1, reserve_days)
        if urgency < 3:
            target = min(target, max(18.0, soft_cap * 0.9))
        elif urgency < 5:
            target = min(target, max(35.0, soft_cap * 1.2))

    target = max(0.0, min(float(budget), float(target)))
    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday immediate behavior (previous_trace only)
    prev_bids = []
    prev_hp_after = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass
        if prev.get('hp_after') is not None:
            try:
                prev_hp_after.append(float(prev.get('hp_after')))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid

    # Estimate scarcity pressure from supply
    # If supply is closer to MIN_SUPPLY, scarcity is higher.
    scarcity = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    # Base bid: aim to win water when scarcity is high, but avoid overpaying.
    # Use yesterday's aggressiveness as a proxy.
    baseline = DAILY_SALARY * (0.45 + 0.25 * scarcity)  # ~40-70

    # If someone yesterday bid extremely high, others likely overcompeted; adjust.
    # Cindy survived with very high bids; treat very high bid as signal of aggressive market.
    if highest_prev_bid >= DAILY_SALARY * 1.6:
        # Compete harder only if I'm at risk.
        if my_hp <= 3 or my_no_water_days >= 2:
            target = max(baseline, highest_prev_bid * 0.65)
        else:
            target = max(baseline, second_prev_bid * 0.85)
    elif highest_prev_bid >= DAILY_SALARY * 0.9:
        # Moderate competition
        if my_hp <= 2 or my_no_water_days >= 2:
            target = max(baseline, highest_prev_bid * 0.55)
        else:
            target = max(baseline, highest_prev_bid * 0.45)
    else:
        # Low competition; bid near baseline.
        target = baseline

    # If I'm critically low hp, bid aggressively.
    if my_hp <= 1:
        target = max(target, DAILY_SALARY * 0.95)
    elif my_hp <= 2:
        target = max(target, DAILY_SALARY * 0.75)

    # Convert target into a feasible bid bounded by budget.
    bid = min(my_budget, target)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    # Small day-based adjustment to avoid ties (deterministic)
    # Use int() to avoid any float index issues (none used here, but keep deterministic).
    day_int = int(day)
    if day_int % 2 == 0:
        bid *= 1.02
    else:
        bid *= 0.98

    bid = min(my_budget, bid)
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_supply = day_context['supply']
    current_day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    david_alive = False
    david_prev_bid = 0.0
    for opp_id, opp_data in opponents_status.items():
        if opp_id == "David" and opp_data['alive']:
            david_alive = True
            prev_trace = opp_data.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                david_prev_bid = prev_trace['bid']
            break

    bid_value = DAILY_SALARY * 0.65

    if my_hp <= 2:
        bid_value = DAILY_SALARY * 0.98
    elif my_hp <= 5:
        bid_value = DAILY_SALARY * 0.85
    elif my_hp > 7 and current_day > EPISODE_DAYS / 2:
        bid_value = DAILY_SALARY * 0.55

    if current_supply <= WATER_REQ + 2:
        bid_value = max(bid_value, DAILY_SALARY * 0.9)
    elif current_supply <= WATER_REQ + 5:
        bid_value = max(bid_value, DAILY_SALARY * 0.8)
    elif current_supply >= WATER_REQ + 10:
        bid_value = min(bid_value, DAILY_SALARY * 0.5)

    if david_alive and david_prev_bid > 0:
        if my_hp <= 5:
            bid_value = max(bid_value, david_prev_bid + 15)
        elif my_hp <= 7:
            bid_value = max(bid_value, david_prev_bid + 8)
        else:
            bid_value = max(bid_value, david_prev_bid + 3)
    else:
        other_yesterday_bids = []
        for opp in alive_opponents:
            prev_trace = opp.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                other_yesterday_bids.append(prev_trace['bid'])

        if other_yesterday_bids:
            highest_other_bid = max(other_yesterday_bids)
            if my_hp <= 5:
                bid_value = max(bid_value, highest_other_bid + 5)
            else:
                bid_value = max(bid_value, highest_other_bid + 2)

    final_bid = max(0.0, min(bid_value, my_budget))

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    cindy = opponents_status.get('Cindy', {})
    cindy_bid = cindy.get('previous_trace', {}).get('bid', 80.0) if cindy.get('alive') else 0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max(cindy_bid * 1.05, 120.0))

    if day_context['supply'] < WATER_REQ * (len(alive_opponents) + 1):
        return min(my_status['budget'], cindy_bid * 0.95)

    return min(my_status['budget'], 65.0)
